import 'package:supabase_flutter/supabase_flutter.dart';

class MoneyAccount{const MoneyAccount({required this.id,required this.name,required this.type,required this.openingBalance,required this.isActive});final String id,name,type;final double openingBalance;final bool isActive;factory MoneyAccount.fromMap(Map<String,dynamic> r)=>MoneyAccount(id:r['id'] as String,name:r['name'] as String,type:r['account_type'] as String,openingBalance:(r['opening_balance'] as num).toDouble(),isActive:(r['is_active']??true) as bool);}
class MoneyAccountRepository{final _client=Supabase.instance.client;Future<List<MoneyAccount>> load(String businessId)async{final rows=await _client.from('irkop_cell_money_accounts').select().eq('business_id',businessId).order('created_at');return rows.map<MoneyAccount>((r)=>MoneyAccount.fromMap(r)).toList();}Future<void> create({required String businessId,required String name,required String type,required double openingBalance})=>_client.from('irkop_cell_money_accounts').insert({'business_id':businessId,'name':name.trim(),'account_type':type,'opening_balance':openingBalance});Future<void> toggle({required String id,required String businessId,required bool active})=>_client.from('irkop_cell_money_accounts').update({'is_active':active}).eq('id',id).eq('business_id',businessId);}